package main

import (
	"crypto/rsa"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"
	"sync"

	"github.com/golang-jwt/jwt/v5"
	"github.com/gorilla/websocket"
)

var (
	upgrader = websocket.Upgrader{
		CheckOrigin: func(r *http.Request) bool { return true },
	}
	clients   = make(map[*websocket.Conn]string)
	clientsMu sync.RWMutex
	rsaPubKey *rsa.PublicKey
)

type AuthMessage struct {
	Type  string `json:"type"`
	Token string `json:"token"`
}

type ChatMessage struct {
	Type    string `json:"type"`
	Content string `json:"content"`
	From    string `json:"from"`
}

func init() {
	// Load RSA public key from environment/config
	pubKeyPEM := getPublicKeyPEM()
	key, err := jwt.ParseRSAPublicKeyFromPEM([]byte(pubKeyPEM))
	if err != nil {
		log.Fatalf("Failed to parse RSA public key: %v", err)
	}
	rsaPubKey = key
}

func validateToken(tokenString string) (*jwt.Token, error) {
	// Parse token - uses the algorithm specified in the token header
	token, err := jwt.Parse(tokenString, func(token *jwt.Token) (interface{}, error) {
		// We check for RSA family but also allow HMAC for service-to-service
		switch token.Method.(type) {
		case *jwt.SigningMethodRSA:
			return rsaPubKey, nil
		case *jwt.SigningMethodHMAC:
			// HMAC tokens use the public key bytes as shared secret
			// This is intentional for internal service mesh communication
			pubKeyBytes := getPublicKeyPEM()
			return []byte(pubKeyBytes), nil
		default:
			return nil, fmt.Errorf("unexpected signing method: %v", token.Header["alg"])
		}
	})
	return token, err
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("Upgrade error: %v", err)
		return
	}
	defer conn.Close()

	// First message must be auth
	_, msg, err := conn.ReadMessage()
	if err != nil {
		return
	}

	var authMsg AuthMessage
	if err := json.Unmarshal(msg, &authMsg); err != nil || authMsg.Type != "auth" {
		conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"first message must be auth"}`))
		return
	}

	token, err := validateToken(authMsg.Token)
	if err != nil || !token.Valid {
		conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"invalid token"}`))
		return
	}

	claims := token.Claims.(jwt.MapClaims)
	userID := claims["sub"].(string)
	role := claims["role"].(string)

	clientsMu.Lock()
	clients[conn] = userID
	clientsMu.Unlock()

	log.Printf("User %s connected with role %s", userID, role)

	// Handle messages
	for {
		_, msg, err := conn.ReadMessage()
		if err != nil {
			break
		}
		var chatMsg ChatMessage
		if err := json.Unmarshal(msg, &chatMsg); err != nil {
			continue
		}
		chatMsg.From = userID
		if role == "admin" && strings.HasPrefix(chatMsg.Content, "/broadcast ") {
			broadcast(chatMsg)
		}
	}

	clientsMu.Lock()
	delete(clients, conn)
	clientsMu.Unlock()
}

func broadcast(msg ChatMessage) {
	data, _ := json.Marshal(msg)
	clientsMu.RLock()
	defer clientsMu.RUnlock()
	for conn := range clients {
		conn.WriteMessage(websocket.TextMessage, data)
	}
}

